ANNOTATIONS = [
    (1, 'before', '整个文件是 React Compiler 的输出：变量名带 s_0 / item_0 / error_0 这类数字后缀，是编译器为消除重复绑定而做的重命名；`newStates[index]!` 的非空断言也是它的手笔'),
    (54, 'before', '父组件的回传通道：setViewState 切到上层菜单、setResult 设一条关闭对话框后展示的结果语。action 与 targetPlugin 是给斜杠命令直连用的——/plugin uninstall foo 会带着目标与动作一次性进到详情页'),
    (63, 'before', '两类「异常条目」各有结构：flagged 是被市场下架的插件（还在设置里，但源没了），failed 是加载失败但设置里仍有记录的插件。它们的展示与可执行动作都不同，所以分成两个类型而不是一个带 kind 的联合'),
    (78, 'before', 'ViewState 是 11 个变体的联合：三个字符串字面量加八个带 type 的对象。带参数的那几个（options schema、cleanup size、flagged/failed 条目、MCP 客户端与工具）把上下文直接嵌进状态，避免再开一堆并列的 useState 让它们失步'),
    (106, 'before', '按市场分组时顺便算启用/禁用计数：列表头的分组标题要用，避免渲染时再遍历一遍'),
    (112, 'before', 'PluginState 是列表项的编辑态：pendingEnable 与 pendingUpdate 是「已操作但未生效」的标记，用来在界面上区分「现在是什么状态」与「刷新后会变成什么状态」'),
    (129, 'before', 'getBaseFileNames 扫一个目录下的 .md 文件并去掉扩展名——插件里的命令与代理都是一目录一文件，文件名就是命令名'),
    (139, 'before', '读目录失败一律降级成空数组而不是抛错：插件详情页即使拿不到组件清单也还该能显示，缺一块信息远好于整页崩掉'),
    (160, 'before', 'getSkillDirNames 与上一个的差别在于「技能是目录不是文件」：每个子目录里得有一个 SKILL.md 才算技能。这里还额外把符号链接算进来，因为技能的常见安装方式就是软链到别处'),
    (168, 'after_block', '目录与软链都试，因为软链可能指向目录（isDirectory 对软链返回 false）'),
    (194, 'before', 'PluginComponentsDisplay 负责「这个插件到底装了什么」：命令、代理、技能、钩子、MCP 服务器五类。数据来源有两处——已加载插件的路径字段，以及 marketplace.json 里的声明，两边都要合并'),
    (215, 'before', '内置插件没有市场条目，只能从注册表里读定义；这是唯一需要特判的来源'),
    (238, 'before', '命令、代理、技能三类的收集逻辑完全同构（单路径加多路径、逐个目录扫），MCP 与钩子则直接取声明的键名——因为后两者的存在形式就是配置对象'),
    (331, 'before', '加载中直接返回 null 而不是转圈：这是详情页的一个小节，闪一下加载态反而更乱'),
    (376, 'before', '本地源插件不能远程更新——直接给出「去改哪个路径」的提示，比让用户点更新然后失败要好'),
    (385, 'before', '按组织策略过滤：被策略禁用的插件不该出现在列表里。注意这里查的是策略设置而不是安装作用域，因为托管设置不会产生 scope 为 managed 的安装记录——按作用域判断会漏'),
    (397, 'before', 'ManagePlugins 是插件管理的主界面，一个组件承担了列表、详情、配置、确认、MCP 子页共 11 个视图。所有视图共享同一份「选中项 + 状态 + 错误」三个状态槽，靠 viewState 分流'),
    (407, 'before', 'MCP 客户端与工具、插件错误都从全局 AppState 订阅——它们由连接管理器维护，组件只读'),
    (413, 'before', '搜索模式要往外同步：父组件据此禁用一些全局快捷键，否则用户在输入框里打字会被当成导航'),
    (424, 'before', 'viewState 的初值恒为 plugin-list：所有进入方式（斜杠命令、直接指定目标插件）都先落到列表，再由自动导航效应跳转'),
    (445, 'before', '两个 ref 而非 state，原因都是「一次性消费」：hasAutoNavigated 防止用户离开后又被拽回详情页（父组件的 targetPlugin 永远不会被清空），pendingAutoActionRef 是同一次跳转之后要执行的动作（如 uninstall）'),
    (455, 'before', 'handleBack 是一个 11 分支的返回逻辑：详情回列表、配置回详情、MCP 工具详情回工具列表、工具列表回服务器详情……每个分支还要顺手清掉不该带到上一层的错误信息'),
    (491, 'before', '落到最后一档时先看有没有待生效的开关：有就只提示「跑 /reload-plugins」，不退出对话框——用户可能还想继续操作'),
    (507, 'before', 'Esc 在大多数视图里等于「返回」，但显式排除两种确认页：confirm-project-uninstall 有自己的 confirm:no 绑定（两处都绑会形成竞争处理器），confirm-data-cleanup 里 n 与 esc 是不同动作（保留数据 vs 取消）'),
    (522, 'before', 'unifiedItems 是这个组件的核心派生数据：把插件、插件内嵌的 MCP、独立 MCP、加载失败的插件、被下架的插件合并成一条扁平列表，按作用域分组再排序。合并的关键约束是「插件的子 MCP 必须紧跟在它后面」，否则排序会把父子关系打散'),
    (531, 'before', '插件内嵌的 MCP 靠命名约定识别：名字形如 plugin:插件名:服务器名。这里把第三段之后全部拼回服务器名，因为服务器名本身可能含冒号'),
    (560, 'before', '启用状态读的是合并后的设置（不是某一个文件的设置），所以组织策略、项目设置、用户设置三层里任何一层禁用都会体现出来'),
    (587, 'before', '孤儿错误 = 插件彻底没加载起来、但设置里还有记录：这些条目不在 loadAllPlugins 的结果里，只能从错误列表反推，否则用户会看到「设置里明明有、界面里找不到」'),
    (612, 'before', 'flag（会话级，来自 --plugin-dir）与 undefined 都归成 user：展示用的作用域模型里没有 flag 这一档，宁可显示成 user 也不能丢条目'),
    (628, 'before', '独立 MCP 排除两类：ide（内置的编辑器集成，不是用户装的）与 plugin: 前缀（已经作为插件子项出现过了）'),
    (644, 'before', '作用域排序表刻意留了 99 这个默认值：未知作用域排最后而不是崩掉。flagged 用 -1 顶到最前面，因为它是最需要用户注意的一类'),
    (720, 'before', '被下架插件的信息（原因、说明文案）从缓存的安全消息文件里查，而不是存在设置里——这样下架名单可以随服务端更新，用户本地只留一个 ID 与时间'),
    (744, 'before', '这一整段 while 循环的存在理由写在注释里：不能直接对整组条目排序，那会打断「插件 → 它的子 MCP」的相邻关系。所以先切成组（插件加紧随其后的缩进 MCP），组内保序、组间按插件名排序，独立的 MCP 再单独排'),
    (786, 'before', '被下架插件只要在列表里出现过就标记为「已看过」，48 小时后自动清除——不标记的话用户每次打开插件管理都会被同一条已读的通知顶到眼前'),
    (794, 'before', '搜索同时匹配名称与描述：用户记得的往往是一句话介绍而不是精确的插件名'),
    (804, 'before', '分页用连续滚动而不是翻页：一屏 8 条，选中项移动时窗口跟着滑动，这样长列表里用方向键一直往下走不会有「翻页断层」'),
    (822, 'before', 'MCPB 检测要读原始 marketplace.json 而不是走 schema 解析后的缓存：老的缓存条目是在 MCPB 支持之前生成的，正规路径读不到这个字段，只有绕过校验直接读文件才能兼容'),
    (860, 'before', '首次加载：跑一遍 loadAllPlugins 拿全部插件的启用与禁用两个列表，再按市场分组、算计数、排序（claude-plugin-directory 永远排第一，其余按字母）'),
    (912, 'before', '作用域优先取 V2 安装记录的 scope；内置插件没有安装记录，直接给 builtin，否则查表会拿到 undefined 并在后面被当成 user，导致内置插件被允许卸载'),
    (932, 'before', '自动导航：斜杠命令带了目标插件时，直接落到详情页。这里把 targetPlugin 当成可能是 name 或 name@marketplace 两种形式解析，因为 parseArgs 是原样透传的'),
    (971, 'before', '成功加载的插件里找不到就查失败列表：用户执行 /plugin uninstall broken-plugin 时，那个插件恰恰是加载失败的，只在错误列表里存在'),
    (986, 'before', '两者都找不到时，只有「带了动作」才关对话框报错。纯粹浏览（/plugin manage）应该停留在列表上，不该被一条「未安装」的提示踢出去'),
    (998, 'before', 'handleSingleOperation 是详情页四个动作（启用/禁用/更新/卸载）的唯一入口，前面是两层权限闸门：内置插件不许更新卸载，托管作用域不许启用禁用卸载（只能更新，因为那是组织下发的版本）'),
    (1018, 'before', 'enabled/disable 刻意不传 scope：这里的 pluginScope 来自 installed_plugins.json（文件缓存的位置），可能与设置里的作用域不一致，传进去会触发「跨作用域操作」的保护性拒绝。让下游自动探测才是对的'),
    (1046, 'before', '卸载前先查「是否在项目级设置里启用」：如果在 .claude/settings.json（团队共享）里启用，直接卸载会让项目里其他人受影响，所以转到一个「只在我本地禁用」的确认页。这里必须直接读设置文件判断，因为 pluginScope 可能是 user 而同一插件同时被项目级启用'),
    (1057, 'before', '有持久数据目录（CLAUDE_PLUGIN_DATA）且这是最后一个安装作用域时才问「要不要连数据一起删」。多作用域安装时下游的 isLastScope 检查本来就不会删，此时再弹窗说「删」却什么都不删，就是在骗用户'),
    (1103, 'before', '四个操作函数自己负责写设置，所以这里只需清缓存。缓存的清理必须在这里做而不是在操作函数里，因为这些函数也被非交互路径调用'),
    (1107, 'before', '操作完不按「操作是不是 enable」来判断要不要弹配置，而是重新读一次设置看插件此刻是否处于启用态：安装流程本身会启用插件，所以从菜单进来时第一项显示的往往是「禁用」'),
    (1124, 'before', '依赖被反向引用的警告必须压成一行：通知的存活时间约 8 秒，多行会被截断；持久记录在错误页里（重载后会出现 dependency-unsatisfied）'),
    (1143, 'before', 'handleSingleOperation 每次渲染都是新函数，直接放进 effect 依赖会让 effect 每次都跑。用 latest-ref 模式：ref 每渲染更新，effect 只依赖 viewState 与 selectedPlugin'),
    (1150, 'before', '自动动作的消费点：导航落到详情页且有待执行动作时才触发，触发前先清空 ref——这个 effect 会因为 viewState 变化重跑，不清空就会重复执行（比如卸载两次）'),
    (1159, 'before', '空格键的即时开关：与详情页里的操作不同，这里是「先改设置、再标记为待生效」，而不是攒到最后一起提交。取消时执行反向操作回到原状态'),
    (1211, 'before', '回车进入详情：按类型分派到五种视图。注意 plugin 类型要回查 pluginStates 拿完整的编辑态，而不是用列表项里那份精简数据'),
    (1258, 'before', '导航键在列表顶部的行为是「向上越界即进入搜索」——这是一个刻意的设计，让用户不用记 / 键也能开始输入'),
    (1284, 'before', '被下架插件的详情页只有一个动作：忽略。忽略后从设置里移除记录，下次不再出现'),
    (1297, 'before', '详情页菜单是动态构建的：启用/禁用恒有；更新/卸载/配置仅非内置有；Mark for update 与 Configure 视清单字段而定；主页与仓库链接视清单字段而定；最后永远有「返回列表」。所以索引导航必须先有这份数组，不能边渲染边算'),
    (1302, 'before', '这里判内置用的是 marketplace 字符串而不是 scope：两者理论上一致，但内置插件的 scope 可能被下游映射过，用市场名更稳'),
    (1338, 'before', '只有检测到 MCPB 才显示 Configure 项——否则点进去必然报「没找到 MCPB 文件」'),
    (1404, 'before', '仓库链接用通用文案而不是 View on GitHub：清单里的 repository 可能是 GitLab、Bitbucket、Azure DevOps，写死 GitHub 会误导。同目录的 pluginDetailsHelpers 保留 GitHub 文案是因为那条路径有显式的 isGitHub 判断'),
    (1447, 'before', '失败插件的详情页只有一个动作：移除。这里做了一件补救——卸载操作失败时，说明这个插件从来没真正安装过（只在 enabledPlugins 里留了记录），于是直接到三个可编辑的设置源里把那条记录抹掉'),
    (1462, 'before', 'deleteDataDir 传 false：这是「加载失败」的恢复路径，插件之后可能被重装，静默删掉数据目录是不可接受的。正常卸载路径会弹窗询问'),
    (1503, 'before', '项目级卸载确认页：确认时直接把 false 写进 settings.local.json。注释说明了为什么不能复用 disablePluginOp——那个函数的跨作用域保护会拒绝这次写入，而这里要的恰恰就是写一条覆盖值'),
    (1541, 'before', '数据清理确认页用原始 useInput 而不是键位绑定，理由有两条：Confirmation 上下文把回车映射成 confirm:yes，那会让「回车」变成删数据的破坏性默认（而界面文案只写了 y 删、n 留）；另外这里 n 与 esc 是两个不同动作（保留数据 vs 取消），而键位系统里两者都映射成 confirm:no'),
    (1556, 'before', '卸载与「删不删数据」在同一次操作里完成：先卸载，再按标志决定是否连带删目录。失败时留在当前页显示错误，成功才回到菜单'),
    (1587, 'before', '搜索词一变就把选中项归零：否则选中索引可能落在新结果集的边界之外，出现「高亮在空行上」'),
    (1593, 'before', '列表页的原始输入处理只做一件事：把任意可打印字符（除 j/k/空格这三个导航键）当成搜索的起始字符。这样用户直接打字就能搜，不用先按 /'),
    (1615, 'before', '加载态是一个全局提前返回，返回到这里时所有 hook 都已经调用过——顺序不能颠倒，否则违反 hook 规则'),
    (1620, 'before', '空态也要给「Esc 返回」的提示：否则用户会以为界面卡住了'),
    (1631, 'before', 'plugin-options 视图：插件已启用，接着问清单里声明的 userConfig。三条出路（配置了/跳过/出错）都走同一个 finish，因为无论配置成败，插件此刻都是启用状态，都要触发「去重载」的提示'),
    (1661, 'before', 'configuring-options 与上面的差别：这里是用户主动点「Configure options」，初始值从已保存的选项里读，保存后回到详情页而不是关闭对话框'),
    (1676, 'before', 'configuring 视图对应 MCPB 的配置流程：保存时要把 MCPB 路径再找一遍（状态里只存了 schema 没存路径），重新加载一次文件才会把配置写进去'),
    (1722, 'before', '被下架插件的详情：只展示「为什么没了」与「什么时候标记的」，动作只有忽略。用 localeDateString 而不是自写格式化，因为这里不是热路径'),
    (1762, 'before', '项目级卸载确认页的文案重点：说明这等价于卸载，但不影响其他协作者。这句话是整个页面的存在理由，必须写在正文里而不是藏进帮助'),
    (1788, 'before', '数据清理确认页把要删的绝对路径直接显示出来：删目录是不可逆操作，用户有权看清到底删哪个路径'),
    (1813, 'before', '插件详情页：作用域、版本、描述、作者、状态、组件清单、错误段、动态菜单、处理中与错误提示、底部快捷键。菜单项的配色按语义分：含 Uninstall 用 error 色，含 Update 用 suggestion 色'),
    (1819, 'before', '详情页也把与该插件相关的错误全捞出来：匹配插件名、完整 ID、或 ID 前缀三种形式，因为错误记录里的 source 字段格式不统一'),
    (1885, 'before', '用 label 里是否包含 Uninstall/Update 来决定颜色，而不是给菜单项加一个 kind 字段——编译产物里这点字符串匹配比多传一个参数便宜，而且标签文案与颜色语义本来就要一起改'),
    (1915, 'before', '失败插件详情：只显示第一条错误的消息，其余错误在列表页的计数里体现。托管作用域的失败插件不给「移除」入口，改为提示联系管理员'),
    (1951, 'before', 'MCP 详情页按配置类型分派到四个组件：stdio 用本地服务器菜单，sse/http/claudeai-proxy 共用远程服务器菜单。三者共用一个组件是因为交互完全一样，只有传输字段不同'),
    (2016, 'before', '兜底分支会直接改状态并返回 null——理论上不可达，但比抛错好：用户看到的是回到列表，而不是整页崩掉'),
    (2022, 'before', '工具列表与工具详情两个视图重复了同一段「按类型拼 ServerInfo」的代码。这是编译产物的常态：原本是内联表达式，被拆成两次独立的构造，不值得为了去重引入运行时判断'),
    (2131, 'before', '主列表：搜索框、无结果提示、上下滚动指示、按作用域分组的条目、底部快捷键、待生效提示。作用域标题只在分组切换处渲染一次，用前一项的 scope 比较得出'),
    (2158, 'before', '作用域标签映射里 dynamic 也显示成 Built-in：动态加载的插件对用户而言就是内置的一部分，没必要暴露内部概念'),
    (2186, 'before', '每一行交给 UnifiedInstalledCell 渲染，它负责缩进（子 MCP）、状态点、待生效标记这些细节。主组件只管分组与排序，两者职责分得很清'),
]
